public class DuplicateIdDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "DuplicateIds",
            "Duplicate ids within a layout",
            "Within a layout, ids should be unique since otherwise `findViewById()` can return an unexpected view.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            new Implementation(DuplicateIdDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );

    private Map<String, List<Element>> mIds;

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Nullable
    @Override
    public Collection<String> getApplicableElements() {
        return ALL;
    }

    @Override
    public void beforeCheckFile(@NonNull Context context) {
        mIds = new HashMap<>();
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        Attr attr = element.getAttributeNodeNS(ANDROID_URI, "id");
        if (attr == null) return;
        String value = attr.getValue();
        if (value.isEmpty()) return;
        String id = value.substring(value.lastIndexOf('/') + 1);
        if (id.isEmpty()) return;
        mIds.computeIfAbsent(id, k -> new ArrayList<>()).add(element);
    }

    @Override
    public void afterCheckFile(@NonNull Context context) {
        XmlContext xmlContext = (XmlContext) context;
        for (Map.Entry<String, List<Element>> entry : mIds.entrySet()) {
            List<Element> elements = entry.getValue();
            if (elements.size() > 1) {
                for (Element element : elements) {
                    Attr attr = element.getAttributeNodeNS(ANDROID_URI, "id");
                    if (attr == null) continue;
                    Location location = xmlContext.getLocation(attr);
                    String message = String.format("Duplicate id `@+id/%1$s` in this layout", entry.getKey());
                    xmlContext.report(ISSUE, element, location, message);
                }
            }
        }
        mIds = null;
    }
}

